/* eslint-disable @typescript-eslint/no-require-imports -- Metro asset requires are the RN way to bundle audio */
import type { AudioPlayer } from 'expo-audio';
import { getSettings, subscribeSettings } from '../store/settings';

/** All sounds are bundled WAVs generated by `scripts/gen-sounds.ts`. Nothing here ever throws. */
const SFX = {
  tap: require('../../assets/sounds/tap.wav'),
  select: require('../../assets/sounds/select.wav'),
  success: require('../../assets/sounds/success.wav'),
  age: require('../../assets/sounds/age.wav'),
  bad: require('../../assets/sounds/bad.wav'),
  coin: require('../../assets/sounds/coin.wav'),
  achievement: require('../../assets/sounds/achievement.wav'),
  death: require('../../assets/sounds/death.wav'),
} as const;
const MUSIC = require('../../assets/sounds/music.wav');

export type SfxName = keyof typeof SFX;

type AudioApi = typeof import('expo-audio');
let api: AudioApi | null | undefined;
const players = new Map<SfxName, AudioPlayer>();
let music: AudioPlayer | null = null;
let musicWanted = false;

function audio(): AudioApi | null {
  if (api !== undefined) return api;
  try {
    api = require('expo-audio') as AudioApi;
    api
      .setAudioModeAsync({ playsInSilentMode: false, interruptionMode: 'mixWithOthers' })
      .catch(() => undefined);
  } catch {
    api = null;
  }
  return api;
}

export function playSfx(name: SfxName): void {
  if (!getSettings().sound) return;
  try {
    const a = audio();
    if (!a) return;
    let p = players.get(name);
    if (!p) {
      p = a.createAudioPlayer(SFX[name]);
      p.volume = 0.7;
      players.set(name, p);
    }
    p.seekTo(0).catch(() => undefined);
    p.play();
  } catch {
    /* audio is best-effort */
  }
}

function applyMusic(): void {
  try {
    const wantOn = musicWanted && getSettings().music;
    if (!wantOn) {
      music?.pause();
      return;
    }
    const a = audio();
    if (!a) return;
    if (!music) {
      music = a.createAudioPlayer(MUSIC);
      music.loop = true;
      music.volume = 0.35;
    }
    if (!music.playing) music.play();
  } catch {
    /* ignore */
  }
}

export function startMusic(): void {
  musicWanted = true;
  applyMusic();
}

export function stopMusic(): void {
  musicWanted = false;
  applyMusic();
}

/** Re-apply the music toggle. Also subscribed to settings changes automatically. */
export function syncAudioWithSettings(): void {
  applyMusic();
}

subscribeSettings(applyMusic);
